'use client';
import { useEffect, useRef, useState, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useCopied, useIsoLayoutEffect, useReducedMotion } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { growFit, Swap, SwapIcon, Tip } from '../lib/motion';
import '../designme.css';
import './response-versions.css';

export interface ResponseVersionsProps {
  /** The person's message the answer replies to, shown as a bubble above it */
  prompt?: ReactNode;
  /** Every version of the answer so far, oldest first */
  versions: string[];
  /** Which version is showing. Leave it out to let the arrows page through them */
  version?: number;
  defaultVersion?: number;
  onVersionChange?: (index: number) => void;
  /** The version showing is still being written. New words fade in as they arrive and paging waits */
  streaming?: boolean;
  /** Quiet text beside the buttons, like "Writing a new version". It shimmers while streaming */
  status?: string;
  /** Called by the regenerate button. Add a version and show it to answer it */
  onRegenerate?: () => void;
  /** Called with the text after it is copied to the clipboard */
  onCopy?: (text: string) => void;
  /** Sits flat in a chat thread (the default, as on designme.dev). Set false to give it a card of its own */
  bare?: boolean;
  className?: string;
}

/** An answer with its earlier versions a click away, plus regenerate and copy. */
export function ResponseVersions({ prompt, versions, version, defaultVersion = 0, onVersionChange, streaming = false, status = '', onRegenerate, onCopy, bare = true, className }: ResponseVersionsProps) {
  const [cur, setCur] = useControllable(version, defaultVersion, onVersionChange);
  const reduce = useReducedMotion();
  const last = Math.max(0, versions.length - 1), at = Math.min(Math.max(cur, 0), last);

  // a different version fades the old text out first; then a finished one comes in all at once, word by word,
  // and one still being written shows its words as they arrive
  const [shown, setShown] = useState(at);
  const [out, setOut] = useState(false);
  const [jump, setJump] = useState(false);
  useEffect(() => {
    if (at === shown) return;
    setOut(true);
    const t = setTimeout(() => { setShown(at); setJump(!streaming); setOut(false); }, reduce ? 0 : 240);
    return () => clearTimeout(t);
  }, [at, shown, streaming, reduce]);
  const text = versions[shown] ?? '';
  const words = text.split(' ').filter(Boolean);
  // the container grows with what it holds, in one smooth motion (growFit, grow() on the site), and stays centred wherever it
  // is centred, in every style (owner, 18 Nov; 26 Nov: no jitter)
  const root = useRef<HTMLDivElement>(null), inner = useRef<HTMLDivElement>(null);
  useIsoLayoutEffect(() => { const el = root.current, w = inner.current; if (el && w) return growFit(el, w); }, []);
  // while a new version streams in, the answer keeps the height of the one it replaces, then eases to its own
  const tRef = useRef<HTMLParagraphElement>(null), prevT = useRef({ at: -1, h: 0 });
  useIsoLayoutEffect(() => {
    const el = tRef.current; if (!el) return;
    if (prevT.current.at !== -1 && prevT.current.at !== shown && prevT.current.h && streaming) el.style.minHeight = prevT.current.h + 'px';
    prevT.current = { at: shown, h: el.style.minHeight ? prevT.current.h : (el.textContent?.trim() ? el.offsetHeight : 0) };
  });
  useEffect(() => {
    const el = tRef.current; if (!el || streaming || !el.style.minHeight) return;
    const was = el.offsetHeight; el.style.minHeight = ''; const h = el.offsetHeight;
    if (h >= was || reduce) return;
    el.style.minHeight = was + 'px'; void el.offsetHeight; el.style.transition = 'min-height var(--dm-t) var(--dm-ease)'; el.style.minHeight = h + 'px';
    const t = setTimeout(() => { el.style.transition = ''; el.style.minHeight = ''; }, 460);
    return () => clearTimeout(t);
  }, [streaming, shown, reduce]);

  const [spin, setSpin] = useState(false);
  const regenerate = () => {
    if (streaming) return;
    setSpin(true); setTimeout(() => setSpin(false), 700);
    onRegenerate?.();
  };
  const [copied, copyText] = useCopied();
  const copy = () => { const t = versions[at] ?? ''; copyText(t); onCopy?.(t); };

  return (
    <div data-dm="" ref={root} className={cx('dm-rvx', !bare && 'dm-panel', 'dm-growing dm-mx-grow', className)} style={bare ? undefined : { padding: 16 }}>
      <div ref={inner} className="dm-grow">
      {prompt && <div className="dm-bub">{prompt}</div>}
      <div className="dm-rvx-a">
        <p ref={tRef} className={cx('dm-msg dm-rvx-t', out && 'dm-out')} aria-live="polite">
          {words.map((w, k) => <span key={shown + ':' + k} className="dm-w" style={jump ? { animationDelay: k * 12 + 'ms' } : undefined}>{w} </span>)}
        </p>
        <div className="dm-rvx-bar dm-mx-ic">
          <div className="dm-rvx-pg">
            <Tip label="Previous"><button type="button" className="dm-ib dm-mx-press" aria-label="Previous version" disabled={at === 0 || streaming} onClick={() => setCur(at - 1)}><Icon name="chev-l" /></button></Tip>
            <span className="dm-rvx-n dm-num">{at + 1} / {Math.max(versions.length, 1)}</span>
            <Tip label="Next"><button type="button" className="dm-ib dm-mx-press" aria-label="Next version" disabled={at === last || streaming} onClick={() => setCur(at + 1)}><Icon name="chev-r" /></button></Tip>
          </div>
          {onRegenerate && <Tip label="Regenerate" kbd="⌘R"><button type="button" className={cx('dm-ib dm-rvx-re dm-mx-press', spin && 'dm-go')} aria-label="Regenerate" onClick={regenerate}><Icon name="refresh" /></button></Tip>}
          <Tip label={copied ? 'Copied to clipboard' : 'Copy'} open={copied || undefined}><button type="button" className={cx('dm-ib dm-rvx-cp dm-mx-press', copied && 'dm-copied')} aria-label="Copy" onClick={copy}><SwapIcon id={copied ? 'check' : 'copy'}><Icon name={copied ? 'check' : 'copy'} /></SwapIcon></button></Tip>
          <Swap className={cx('dm-rvx-st dm-muted', streaming && status && 'dm-shim')}>{status}</Swap>
        </div>
      </div>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Response versions ---------- */
.dm-rvx{display:flex;flex-direction:column;gap:14px}
/* its motion (the core's motion pieces, owner, 26 Nov): a press on its buttons shows at once (.mx-press); Copy's icon and its
   tick crossfade (.mx-ic); the answer eases to its new height on the spring (.mx-grow) */
.dm-rvx-a{display:flex;flex-direction:column;gap:var(--dm-s-2)}
/* the answer is as tall as its words in every style (owner's notes, 18 Nov): the component grows with them (grow()), and a
   version streaming in keeps the height of the one it replaces, then eases to its own. The bar's first button reaches 6px
   past the column, so the growing box lets that much show, focus ring included */
.dm-rvx.dm-growing{overflow-clip-margin:12px}
/* nothing in the bar shrinks on a click (owner, 18 Nov) */
.dm-rvx-bar .dm-ib:active{transform:none}
:root[data-style="clean"] .dm-rvx-bar .dm-ib:active,:root [data-style="clean"] .dm-rvx-bar .dm-ib:active,:root [data-style="clean"].dm-rvx-bar .dm-ib:active{transform:none}
.dm-rvx-t .dm-w{animation:dm-rvw .45s var(--dm-ease) both}
@keyframes dm-rvw{from{opacity:0;filter:blur(4px)}to{opacity:1;filter:none}}
.dm-rvx-t.dm-out{animation:dm-rvo .3s var(--dm-ease) both}
@keyframes dm-rvo{to{opacity:0;filter:blur(4px);transform:translateY(-2px)}}
.dm-rvx-bar{display:flex;align-items:center;gap:2px;margin-left:-6px}
/* its icon buttons, the pager's included, are the library's 28px icon buttons */
.dm-rvx-bar .dm-ib{width:28px;height:28px}
.dm-rvx-pg{display:flex;align-items:center;gap:0}
.dm-rvx-pg .dm-ib[disabled]{opacity:1;cursor:not-allowed;background:none;color:var(--dm-dis)}
/* the bar sits on the stage, where --dm-row is the stage's own colour: it sets --dm-row to a quiet 5% of the text colour, as the
   other cards on the stage do, so its buttons keep the one shared hover */
.dm-rvx-bar{--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
.dm-rvx-n{font-size:12px;color:var(--dm-muted);min-width:34px;text-align:center}
.dm-rvx-re svg{transition:transform .7s var(--dm-ease)}
.dm-rvx-re.dm-go svg{transform:rotate(360deg)}
.dm-rvx-st{font-size:12px;margin-left:6px}
/* Clean (owner, 18 Nov): words fade in and out without a blur */
@keyframes dm-rvwc{from{opacity:0}to{opacity:1}}
@keyframes dm-rvoc{to{opacity:0;transform:translateY(-2px)}}
:root[data-style="clean"] .dm-rvx-t .dm-w,:root [data-style="clean"] .dm-rvx-t .dm-w,:root [data-style="clean"].dm-rvx-t .dm-w{animation-name:dm-rvwc;animation-duration:var(--dm-t-slow)}
:root[data-style="clean"] .dm-rvx-t.dm-out,:root [data-style="clean"] .dm-rvx-t.dm-out,:root [data-style="clean"].dm-rvx-t.dm-out{animation-name:dm-rvoc;animation-duration:var(--dm-t)}
/* Clean (owner, 22 Nov: "differentiate Clean from Soft"): the answer is a version card. The answer comes first, 16px in
   from the card's edges; under it a hairline, and under that the bar as a plain row with no strip (owner, 23 Nov: "just add
   a divider line"): the arrows and the count on the left with what is happening beside them, Regenerate and Copy at the
   right. Its buttons are 28px, 16px from the hairline, the card's bottom edge and its sides. Soft and Blueprint keep the
   answer flat in the thread with its bar under it, in the same order */
:root[data-style="clean"] .dm-rvx-a,:root [data-style="clean"] .dm-rvx-a,:root [data-style="clean"].dm-rvx-a{gap:0;background:var(--dm-surface);border-radius:var(--dm-r-card);box-shadow:var(--dm-shadow);overflow:hidden}
:root[data-style="clean"] .dm-rvx-bar,:root [data-style="clean"] .dm-rvx-bar,:root [data-style="clean"].dm-rvx-bar{margin:0;padding:16px;border-top:1px solid var(--dm-line)}
:root[data-style="clean"] .dm-rvx-t,:root [data-style="clean"] .dm-rvx-t,:root [data-style="clean"].dm-rvx-t{padding:16px}
:root[data-style="clean"] .dm-rvx-st,:root [data-style="clean"] .dm-rvx-st,:root [data-style="clean"].dm-rvx-st{order:1;margin-left:var(--dm-s-2);min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
:root[data-style="clean"] .dm-rvx-re,:root [data-style="clean"] .dm-rvx-re,:root [data-style="clean"].dm-rvx-re{order:2;margin-left:auto}
:root[data-style="clean"] .dm-rvx-cp,:root [data-style="clean"] .dm-rvx-cp,:root [data-style="clean"].dm-rvx-cp{order:3}
.dm-rvx-cp.dm-copied,.dm-aab-cp.dm-copied{color:var(--dm-ok-mark)!important}
